import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:]

    bit = [0] * (n + 1)

    def add(i, v):
        while i <= n:
            bit[i] += v
            i += i & -i

    def sum_prefix(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0
    for x in p:
        smaller_left = sum_prefix(x - 1)
        smaller_right = (x - 1) - smaller_left
        ans += smaller_right * smaller_left + smaller_right * (smaller_right + 1) // 2
        add(x, 1)

    print(ans)

